    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable {
        require(amount > 0);
        address recv = address(this);
        uint before = recv.balance;
        bool reverted;
        c.sendTo(recv, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted || (recv.balance == before + amount));
